void rsr_err_add (Rsr_Err_Code code)
{  
  
      UInt8 ptr = rsr_err.count %RSR_ERR_BUFF_SIZE ;
     
      rsr_err.code[ptr] = code ;
    
      rsr_err.count++ ;
    
}

